package com.donotmiss.backend.aiapplication.career.gap;
import com.donotmiss.backend.aiapplication.agent.*; import com.donotmiss.backend.aiapplication.llm.*; import com.donotmiss.backend.aiapplication.trace.TraceService; import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.Test; import java.time.Instant; import java.util.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class GapSemanticAssessmentRuntimeTest {
 @Test void drivesSemanticAssessmentThroughRuntimeToolAndGateway(){LlmGateway gateway=mock(LlmGateway.class);TraceService trace=mock(TraceService.class);when(gateway.complete(any())).thenReturn(Optional.of(new LlmResponse("{\"supported\":true,\"evidenceStrength\":\"STRONG\",\"confidence\":0.9,\"reason\":\"project evidence\"}","mock",new LlmUsage(1,1,2),"stop",1,"r",Map.of())));GapSemanticAssessmentTool tool=new GapSemanticAssessmentTool(gateway,new ObjectMapper());AgentRuntime runtime=new SimpleAgentRuntime(name->Optional.of(tool),trace);AgentResult result=runtime.run(new GapSemanticAssessmentAgent(),new AgentContext(1L,2L,"u","candidate-job-gap-semantic-agent","assess",AgentState.PREPARING,Map.of("requirement",Map.of("skillCode","JAVA_BACKEND"),"candidateEvidence",List.of(Map.of("evidenceId",1,"skillCode","JAVA_BACKEND","text","API")),"requirementId",7L,"evidenceCount",1),List.of(),Instant.now()));assertThat(result.nextState()).isEqualTo(AgentState.COMPLETED);verify(gateway).complete(any(LlmRequest.class));verify(trace).recordToolInvocation(any(AgentToolInvocation.class));}
}
